// Some portions generated by Codex. Benchmark-only streaming line framing.
// Scan each incoming decoded chunk once. Join a fragmented line only at its delimiter.
export class LineSplitter {
  #fragments = [];
  *push(text) {
    let start = 0;
    while (start < text.length) {
      const end = text.indexOf('\n', start);
      if (end < 0) {
        this.#fragments.push(text.slice(start));
        return;
      }
      const piece = text.slice(start, end);
      let line = piece;
      if (this.#fragments.length) {
        this.#fragments.push(piece);
        line = this.#fragments.join('');
        this.#fragments = [];
      }
      start = end + 1;
      yield line;
    }
  }
  finish(text = '') {
    // Preserve the old client: decoder flush is tail, never a newly parsed record.
    this.#fragments.push(text);
    const tail = this.#fragments.join('');
    this.#fragments = [];
    return tail;
  }
}
